function parseState(raw){let t=raw.trim();const ignore=[/계단(?:은|이|도)?\s*(?:괜찮|상관없|문제없)[^,.。\n]*/g,/(?:쉬거나|쉬는 것|휴식|쉴 곳|벤치)(?:은|는|이|가)?\s*(?:필요 없|필요없|상관없)[^,.。\n]*/g,/(?:경사|오르막)(?:는|은|가)?\s*(?:괜찮|상관없|문제없)[^,.。\n]*/g];for(const re of ignore)t=t.replace(re,' ');const wheelchair=/휠체어/.test(t)&&!/휠체어(?:는|가)?\s*(?:아니|안\s*타|사용하지 않)/.test(t),stroller=/유모차/.test(t),knee=/무릎|목발|관절|다리.*(?:아프|아파|불편)|보행\s*보조/.test(t);const avoidSteps=wheelchair||stroller||knee||/(?:계단|층계).*(?:피하|피해|싫|어렵|힘|못|불가|이용할 수 없|없|안)|계단\s*없이/.test(t);const avoidSlope=wheelchair||stroller||knee||/(?:경사|오르막|언덕).*(?:피하|피해|낮|완만|힘|어렵|싫|못)|평지/.test(t);const rest=/(?:쉬|쉴|휴식|벤치|앉)|오래\s*걷.*(?:힘|어렵)/.test(t);const short=/짧|가까|최단|빨리|급해|거리.*최소/.test(t);const minutes=t.match(/(\d{1,2})\s*분\s*(?:마다|간격)/);return {raw,wheelchair,avoidSteps,avoidSlope,rest,short,restMinutes:minutes?Math.max(1,Number(minutes[1])):null,speed:wheelchair?55:knee?45:65,recognized:avoidSteps||avoidSlope||rest||short||wheelchair,source:'이 기기에서 문장 규칙으로 해석'};}
class Heap{constructor(){this.a=[]}push(v){let a=this.a,i=a.length;a.push(v);while(i){let p=(i-1)>>1;if(a[p][0]<=v[0])break;a[i]=a[p];i=p}a[i]=v}pop(){let a=this.a,out=a[0],v=a.pop();if(a.length){let i=0;while(i*2+1<a.length){let c=i*2+1;if(c+1<a.length&&a[c+1][0]<a[c][0])c++;if(a[c][0]>=v[0])break;a[i]=a[c];i=c}a[i]=v}return out}}
function createGraph(data){const all=new Map(data.elements.map(e=>[e.type+e.id,e]));const nodes=new Map([...all.values()].filter(e=>e.type==='node').map(n=>[n.id,{...n,ll:[n.lat,n.lon],edges:[]} ]));const ways=[];const allowed=new Set(['footway','path','pedestrian','residential','living_street','service','steps','unclassified','tertiary','secondary','primary','track','cycleway']);for(const w of all.values()){const t=w.tags||{};if(w.type!=='way'||!allowed.has(t.highway)||t.area==='yes'||t.foot==='no'||t.foot==='private'||(['no','private'].includes(t.access)&&!['yes','designated','permissive'].includes(t.foot))||t.highway==='cycleway'&&!['yes','designated','permissive'].includes(t.foot))continue;const incline=/^-?\d+(\.\d+)?%?$/.test(t.incline||'')?Math.abs(parseFloat(t.incline)):null;const meta={id:w.id,name:t.name||({footway:'보행로',path:'산책로',steps:'계단',service:'진입로',residential:'생활도로'}[t.highway]||'일반 도로'),highway:t.highway,steps:t.highway==='steps',incline,wheelchair:t.wheelchair,rough:['unpaved','gravel','ground','dirt','sand','cobblestone'].includes(t.surface),road:['primary','secondary','tertiary','unclassified','residential','service'].includes(t.highway),sidewalk:t.sidewalk};ways.push({...w,meta});for(let i=1;i<w.nodes.length;i++){const a=nodes.get(w.nodes[i-1]),b=nodes.get(w.nodes[i]);if(!a||!b)continue;const d=distance(a.ll,b.ll),key=[a.id,b.id].sort().join('-');a.edges.push({to:b.id,d,key,...meta});b.edges.push({to:a.id,d,key,...meta})}}
const used=new Map([...nodes].filter(([,n])=>n.edges.length));const seen=new Set(),components=[];for(const id of used.keys()){if(seen.has(id))continue;const q=[id];seen.add(id);for(let i=0;i<q.length;i++)for(const e of used.get(q[i]).edges)if(!seen.has(e.to)){seen.add(e.to);q.push(e.to)}components.push(q)}components.sort((a,b)=>b.length-a.length);const main=new Set(components[0]);const graph={nodes:used,ways,main,places:[],benches:[],meta:{timestamp:data.osm3s?.timestamp_osm_base}};for(const e of all.values()){const t=e.tags||{},ll=e.lat?[e.lat,e.lon]:e.center?[e.center.lat,e.center.lon]:null;if(!ll)continue;if(t.amenity==='bench')graph.benches.push({ll,id:e.id,name:t.name||'OSM 등록 벤치'});if(t.name&&(['cafe','library','school','community_centre'].includes(t.amenity)||t.highway==='bus_stop'))graph.places.push({ll,name:t.name,id:e.id,type:t.amenity||'bus_stop'})}graph.places.sort((a,b)=>distance(a.ll,school)-distance(b.ll,school));return graph;}
function nearest(g,ll,opts={}){let result=null,best=Infinity;for(const n of g.nodes.values()){if(!g.main.has(n.id))continue;const t=n.tags||{};if(['no','private'].includes(t.access)||['wall','fence','stile','turnstile'].includes(t.barrier)||opts.wheelchair&&['cycle_barrier','bollard','gate'].includes(t.barrier)&&t.wheelchair!=='yes')continue;const d=distance(ll,n.ll);if(d<best){best=d;result=n}}return result?{node:result,gap:best}:null}
function cost(e,p,penalty){if(p.avoidSteps&&e.steps||p.wheelchair&&e.wheelchair==='no')return Infinity;let c=e.d;if(p.avoidSlope){if(e.incline!==null)c*=1+e.incline*.28;else c*=1.35}if(p.wheelchair||p.avoidSlope){if(e.rough)c*=2.8;if(e.road&&!['yes','both','left','right','separate'].includes(e.sidewalk))c*=1.45}if(!p.short&&e.road)c*=1.12;if(e.steps)c*=1.7;if(penalty?.has(e.key))c*=2.8;return c}
function shortest(g,start,end,p,penalty){const h=new Heap(),dist=new Map([[start,0]]),prev=new Map();h.push([0,start]);while(h.a.length){const [d,id]=h.pop();if(d!==dist.get(id))continue;if(id===end){const edges=[],ids=[end];let at=end;while(at!==start){const x=prev.get(at);if(!x)return null;edges.unshift(x.edge);at=x.from;ids.unshift(at)}return {ids,edges,length:edges.reduce((s,e)=>s+e.d,0),cost:d}}for(const e of g.nodes.get(id).edges){const n=g.nodes.get(e.to),t=n.tags||{};if(['no','private'].includes(t.access)||['wall','fence','stile','turnstile'].includes(t.barrier)||p.wheelchair&&t.wheelchair==='no')continue;const nd=d+cost(e,p,penalty);if(nd<(dist.get(e.to)??Infinity)){dist.set(e.to,nd);prev.set(e.to,{from:id,edge:e});h.push([nd,e.to])}}}return null}
function route(g,from,to,p){const a=nearest(g,from,p),b=nearest(g,to,p);if(!a||!b||a.gap>180||b.gap>180)throw Error('출발지 또는 목적지가 연결된 보행 네트워크에서 너무 멀어요. 지도에서 주변 길을 선택해 주세요.');if(a.node.id===b.node.id)throw Error('출발지와 목적지가 너무 가까워요. 다른 목적지를 선택해 주세요.');const base=shortest(g,a.node.id,b.node.id,p);if(!base)throw Error('입력 조건으로 연결 가능한 경로가 없어요. 다른 목적지를 선택하거나 조건을 조정해 주세요.');let best=base,restStop=null;const messages=[];if(p.rest){const candidates=g.benches.map(x=>({...x,score:distance(from,x.ll)+distance(x.ll,to)})).filter(x=>distance(x.ll,from)<1600).sort((x,y)=>x.score-y.score).slice(0,12);let bestCost=Infinity;for(const bench of candidates){const n=nearest(g,bench.ll,p);if(!n||n.gap>35)continue;const one=shortest(g,a.node.id,n.node.id,p),two=shortest(g,n.node.id,b.node.id,p);if(!one||!two||one.length+two.length>base.length+700)continue;if(p.restMinutes&&one.length/p.speed>p.restMinutes)continue;if(one.cost+two.cost<bestCost){bestCost=one.cost+two.cost;best={ids:[...one.ids,...two.ids.slice(1)],edges:[...one.edges,...two.edges],length:one.length+two.length,cost:bestCost};restStop={...bench,snap:n.node.ll,gap:n.gap,firstDistance:one.length}}}if(!restStop)messages.push('허용한 우회 범위에서 경유 가능한 벤치를 찾지 못했어요. 휴식 조건은 충족되지 않았습니다.');else if(p.restMinutes)messages.push(`${p.restMinutes}분마다 쉬는 전체 일정은 보장하지 못해요. 첫 휴식 지점까지 약 ${Math.ceil(restStop.firstDistance/p.speed)}분입니다.`)}
const unknown=best.edges.filter(e=>e.incline===null).reduce((s,e)=>s+e.d,0);if(p.avoidSlope&&unknown>0)messages.push(`경사 데이터 미확인 ${Math.round(unknown)}m · 완만한 경로인지 확인이 필요해요.`);if(p.wheelchair)messages.push('보도 턱·폭·출입구는 미검증입니다. 휠체어 통행 가능을 보장하지 않아요.');return {...best,from:a.node.ll,to:b.node.ll,gaps:[a.gap,b.gap],restStop,messages,unknown,minutes:Math.max(1,Math.ceil(best.length/p.speed)),coords:best.ids.map(id=>g.nodes.get(id).ll)};}
